#include<bits/stdc++.h>
#include<atcoder/all>

using namespace std;
using namespace atcoder;

using S=int;
using F=int;

S op(S l,S r){return min(l,r);}
S e(){return 1e9;}
S mapping(F l,S r){return (l+r);}
F composition(F l,F r){return (l+r);}
F id(){return 0;}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n;
  string s;
  cin >> n >> s;
  vector<S> ini(n+1,0);
  for(int i=0;i<n;i++){
    if(s[i]=='A'){ini[i+1]=ini[i]+1;}
    else{ini[i+1]=ini[i]-1;}
  }
  lazy_segtree<S,op,e,F,mapping,composition,id> seg(ini);
  int q;
  cin >> q;
  while(q--){
    int typ;
    cin >> typ;
    if(typ==1){
      int i;
      string c;
      cin >> i >> c;
      i--;
      int del;
      if(s[i]=='A'){del=-1;}
      else{del=1;}
      s[i]=c[0];
      if(s[i]=='A'){del++;}
      else{del--;}
      seg.apply(i+1,n+1,del);
    }
    else{
      int l,r;
      cin >> l >> r;
      l--;
      if(seg.prod(l,r+1)==seg.get(l)){cout << "Yes\n";}
      else{cout << "No\n";}
    }
  }
  return 0;
}
